{
  "name": "pr-lifecycle",
  "version": "1.3.0",
  "description": "/pr-gate across the PR lifecycle: pre-PR Codex rounds, then the repository's own post-PR reviews, under one review budget and one record, with a live progress pane.",
  "author": {
    "name": "adam schoen"
  },
  "license": "MIT",
  "types": "./types/index.d.ts",
  "userConfig": {
    "allowanceStandard": {
      "type": "number",
      "title": "Review rounds, standard changes",
      "description": "Discretionary review rounds one lifecycle may complete on a standard change, before and after the PR opens together, advisory rounds included. The protected post-PR rounds do not count. Replaces maxRounds, which is read when this is unset. A repository's .github/pr-gate.json on the base can set its own.",
      "default": 4
    },
    "allowanceHigh": {
      "type": "number",
      "title": "Review rounds, high blast-radius changes",
      "description": "The same allowance for a high blast-radius change. A repository's .github/pr-gate.json on the base can set its own.",
      "default": 6
    },
    "allowanceLight": {
      "type": "number",
      "title": "Review rounds, light lane",
      "description": "The same allowance for a branch on the light lane (lightBranches), unless its blast radius is high: then it takes the full lane and allowanceHigh. A repository's .github/pr-gate.json on the base can set its own.",
      "default": 3
    },
    "bases": {
      "type": "string",
      "title": "Gated base branches",
      "description": "Comma-separated base branches whose PRs must pass the gate first. The first one is the default base.",
      "default": "dev,main"
    },
    "enforce": {
      "type": "boolean",
      "title": "Block ungated PRs",
      "description": "Deny `gh pr create` (and the GitHub MCP create-PR tool) to a gated base until the gate has finished for the current HEAD, and start the gate when one is denied.",
      "default": true
    },
    "enforceMerge": {
      "type": "boolean",
      "title": "Hold merges until the lifecycle is done",
      "description": "Deny merging a PR to a gated base (gh, gh api, GitHub MCP tools) until its lifecycle review is complete for the PR's current head, or the person waived it.",
      "default": true
    },
    "fixer": {
      "type": "string",
      "title": "Who fixes findings",
      "description": "main sends each round's findings back to the main agent; subagent hands them to a fresh sub-agent.",
      "default": "main",
      "options": [
        "main",
        "subagent"
      ]
    },
    "fixReview": {
      "type": "string",
      "title": "Review the fix before the next round",
      "description": "A separate sub-agent checks the fix commits before Codex sees them again. auto does this only for high blast-radius changes.",
      "default": "auto",
      "options": [
        "auto",
        "always",
        "never"
      ]
    },
    "onExhausted": {
      "type": "string",
      "title": "After the last round without agreement",
      "description": "open-pr opens the PR anyway when the pre-PR allowance is spent (never with an open security P1); stop leaves it held for a person's decision. Either way the post-PR lifecycle still runs, and merging stays held. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "open-pr",
      "options": [
        "open-pr",
        "stop"
      ]
    },
    "openPr": {
      "type": "boolean",
      "title": "Ask the main agent to open the PR",
      "description": "When the gate finishes, prompt the main agent to push and open the PR following the repository's own rules.",
      "default": true
    },
    "highRiskPaths": {
      "type": "string",
      "title": "High blast-radius paths",
      "description": "A regular expression over changed file paths. A match raises the tier to high: Codex challenge mode runs in parallel with the review, on codexModelHigh at highEffort, and fixes are reviewed before the next round. A submodule pointer to a commit already on that submodule's origin/main or origin/dev is not counted. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "(^|/)(migrations?|auth|security|secrets?)(/|\\.|$)|^server/|^Backend$|^\\.github/workflows/|cloudbuild|Dockerfile|(^|/)(package(-lock)?\\.json|uv\\.lock|pyproject\\.toml)$"
    },
    "reviewEffort": {
      "type": "string",
      "title": "Codex effort, standard changes",
      "description": "The reasoning effort Codex starts at on a standard change. A high blast-radius change (highRiskPaths, or a large diff) starts at highEffort, a light-lane branch at lightEffort. When Codex times out, the round reruns one level lower, down to low; the next run on that branch starts a level below where the timed-out one ended. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "medium",
      "options": [
        "medium",
        "low",
        "high"
      ]
    },
    "lightBranches": {
      "type": "string",
      "title": "Light-lane branches",
      "description": "A regular expression over the branch name. A matching branch gets one Codex round and no advisory rounds; whatever Codex raises goes to the pull request's own review. A pointer bump, version-only bump or already-landed commits pass without Codex on any branch. Empty turns the light lane off. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "^chore/"
    },
    "lightEffort": {
      "type": "string",
      "title": "Codex effort, light-lane branches",
      "description": "The effort Codex starts at on a light-lane branch that is not high blast radius. A high blast-radius change starts at highEffort. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "low",
      "options": [
        "low",
        "medium",
        "high"
      ]
    },
    "highEffort": {
      "type": "string",
      "title": "Codex effort, high blast-radius changes",
      "description": "The effort Codex starts at on a high blast-radius change (highRiskPaths, or a large diff), light lane or not. A timeout steps it down as for the other tiers. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "medium",
      "options": [
        "medium",
        "low",
        "high"
      ]
    },
    "rereviewEffort": {
      "type": "string",
      "title": "Codex effort, re-reviews",
      "description": "The effort of every Codex dispatch after the first completed round Codex ran in: later rounds, the consult of earlier rebuttals and fixes, the post-PR rebuttal check, and the post-PR Codex fallback. Never above the tier's starting effort. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "low",
      "options": [
        "low",
        "medium",
        "high"
      ]
    },
    "codexModel": {
      "type": "string",
      "title": "Codex model, standard and light-lane changes",
      "description": "The Codex model the gate names to the gstack /codex skill (--model, GSTACK_CODEX_MODEL) on a change that is not high blast radius. Empty names none, so gstack's own order applies (GSTACK_CODEX_MODEL, then Codex config.toml). Every Codex step uses it, the post-PR rebuttal check included. A model gstack cannot use, or a step that reports another model, stops the round; it never falls back to another. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "gpt-6-luna"
    },
    "codexModelHigh": {
      "type": "string",
      "title": "Codex model, high blast-radius changes",
      "description": "The Codex model the gate names on a high blast-radius change. Empty names none, so gstack's own order applies. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "gpt-6-astra"
    },
    "runnerModel": {
      "type": "string",
      "title": "Claude model, Codex runners",
      "description": "The Claude model of the sub-agents that run Codex: the review, the challenge and the post-PR rebuttal check. An alias (sonnet, opus, haiku) or a full id; empty inherits the session's model. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "sonnet"
    },
    "fixAgentModel": {
      "type": "string",
      "title": "Claude model, fixer and fix reviewer",
      "description": "The Claude model of the fix sub-agent (fixer: subagent) and the sub-agent that reviews a fix. An alias or a full id; empty inherits the session's model. A repository's .github/pr-gate.json on the base can set its own.",
      "default": "opus"
    },
    "stepTimeoutMinutes": {
      "type": "number",
      "title": "Step timeout (minutes)",
      "description": "How long one agent step may run before the gate stops with an error.",
      "default": 30
    },
    "routineRoundMinutes": {
      "type": "number",
      "title": "Routine round timebox (minutes)",
      "description": "The active time a routine round should take. Going over is shown and recorded, not failed; stepTimeoutMinutes is the hard limit.",
      "default": 3
    },
    "waitCapMinutes": {
      "type": "number",
      "title": "Reviewer wait cap (minutes)",
      "description": "The longest a post-PR round waits for reviewers before it carries on with what arrived. A repository's .github/pr-gate.json on the base can set its own.",
      "default": 20
    },
    "quietMinutes": {
      "type": "number",
      "title": "Quiet period (minutes)",
      "description": "Without a roster file, collection ends once checks are done and no new feedback arrived for this long. A repository's .github/pr-gate.json on the base can set its own.",
      "default": 3
    }
  }
}

files.types/index.d.ts:
export type Severity = 'P0' | 'P1' | 'P2' | 'P3'

/** open is the spec's "still unresolved". fixed is split: what the fixer reported, and what a check confirmed. */
export type FindingStatus = 'open' | 'reported-fixed' | 'verified-fixed' | 'rebutted' | 'deferred'

export type FindingSource = 'codex-review' | 'codex-challenge' | 'github'

export type FindingEvent = { round: number; status: FindingStatus; note?: string; evidence?: string; by: string; at: number }

export type Finding = {
  id: string
  /** The round that first raised it (the spec's firstRound). */
  round: number
  source: FindingSource
  /** A GitHub login, or 'codex'. */
  reviewer: string
  /** The GitHub id of the review or comment it came from: `review:<id>`, `inline:<id>`, `comment:<id>`. */
  externalId?: string
  threadId?: string
  url?: string
  severity: Severity
  isSecurity?: boolean
  title: string
  file?: string
  line?: number
  detail?: string
  /** The head it was raised on. */
  headSeen: string
  status: FindingStatus
  note?: string
  /** A later change touched its file: the evidence behind its status needs checking again. */
  needsRecheck?: boolean
  /** The head `line` was last placed at (R73): a head move reads the diff from here and shifts `line` along with the code. */
  lineHead?: string
  history: FindingEvent[]
}

export type StepState = 'pending' | 'running' | 'done' | 'failed' | 'skipped'

export type Step = { id: string; label: string; state: StepState; detail?: string }

export type Role = 'review' | 'challenge' | 'fix' | 'verify' | 'triage'

export type Pending = {
  role: Role
  /** The step's name, which the agent repeats in its trailer. */
  step: string
  /** A sub-agent's id, as the engine gave it. */
  agentId?: string
  /** True for the main agent, which has no id. */
  isMain?: true
  /** Main agent only: the main-loop turn that began with this step's prompt (its step marker in the turn's text, R51). */
  turnId?: string
  answer?: string
}

export type RunStatus =
  | 'running'
  | 'passed'
  | 'exhausted'
  | 'blocked'
  | 'error'
  | 'stopped'
  | 'waived'

export type Tier = 'trivial' | 'standard' | 'high'

/** Codex reasoning effort. Never xhigh: those reviews timed out. */
export type Effort = 'high' | 'medium' | 'low'

/** full: the whole gate. light: a branch named by `lightBranches` (chore/), one round and no advisories. */
export type Lane = 'full' | 'light'

export type LifecyclePhase = 'pre' | 'post' | 'ready' | 'archived'

/** baseline rounds and the final-head check are free; discretionary ones draw on the allowance. */
export type RoundKind = 'baseline' | 'discretionary' | 'final-head-check'

/** The Codex model each role reported from gstack's `CODEX_MODEL:` line (R69): the review, the challenge, the rebuttal check. */
export type RanModels = { review?: string; challenge?: string; verify?: string }

export type Evidence = { source: 'codex' | 'github'; reviewer: string; head: string; isComplete: boolean }

export type RoundRecord = {
  /** The iteration label (`Run.round`); not a count of rounds consumed. */
  n: number
  phase: 'pre' | 'post'
  kind: RoundKind
  /** An advisory-only round: it draws under the reserve rule. */
  isAdvisory: boolean
  startHead: string
  endHead: string
  /** The PR base the round reviewed against; a pre-PR round's verdict covers that base only. */
  base?: string
  isCompleted: boolean
  /** The Codex effort the round, or the attempt, ran at. Absent on a record from before 1.2.0. */
  effort?: Effort
  /** The Codex model that reviewed it, from the reviewer's `CODEX_MODEL:` line, else the model the gate named (R69). */
  codexModel?: string
  /** Every role's reported model, kept apart when they differ (R69). */
  ranModels?: RanModels
  evidence: Evidence[]
  raised: { blocking: number; advisory: number }
  rebutted: number
  deferredBlocking: number
  activeMs: number
  waitMs: number
  outstanding?: string
  startedAt: number
  endedAt: number
}

/** A finding waiver lapses when its finding's file changes after it was given (R55): `lapsedHead` is the head that changed it. */
export type Waiver = {
  scope: 'pre' | 'post' | 'finding'
  findingId?: string
  head: string
  /** A pre waiver's base: it lets a PR open only to that base (R1-1). One without it matches none. */
  base?: string
  reason: string
  by: string
  at: number
  lapsedAt?: number
  lapsedHead?: string
}

export type Grant = { n: number; reason: string; head: string; at: number }

/**
 * One line of the run log (`/pr-gate log`): what cost time or needed the person. stop: a run ended short of done (error, blocked,
 * stopped, exhausted); end: a run ended done; person: a /pr-gate command; head: the gate caught up to a head itself; session: a
 * session took the record over, or stood down.
 */
export type LogEntry = { at: number; kind: 'stop' | 'end' | 'person' | 'head' | 'session' | 'check'; text: string }

export type LifecycleRecord = {
  version: 1
  root: string
  branch: string
  base: string
  /** owner/repo, lowercased. */
  slug?: string
  pr?: number
  /** The gh login of this machine, so its own replies are not read as feedback. */
  self?: string
  head: string
  tier: Tier
  tierWhy: string
  lane: Lane
  /** Set when a pass-through skipped pre-PR Codex: why. */
  passThrough?: string
  allowance: number
  grants: Grant[]
  attempts: number
  activeMs: number
  waitMs: number
  /** The run log, oldest first, capped at LOG_CAP entries. Absent on a record from before 1.3.0. */
  log?: LogEntry[]
  rounds: RoundRecord[]
  findings: Finding[]
  /** Feedback ids already triaged. */
  processed: string[]
  /** Feedback id to the id of the reply posted to it. */
  replies: Record<string, string>
  waivers: Waiver[]
  phase: LifecyclePhase
  /** The pre-PR verdict, and the head it is for. */
  preStatus?: RunStatus
  preHead?: string
  /** Why the post-PR phase stopped short of ready. */
  /** awaiting-decision: only deferrals hold the merge, and only the person's waiver releases them (R39). */
  postStatus?: 'exhausted' | 'blocked' | 'awaiting-decision' | 'error' | 'stopped'
  message?: string
  effort?: Effort
  hasTimedOut?: boolean
  passedEffort?: Effort
  updatedAt: number
}

export type Run = {
  id: string
  cwd: string
  root: string
  branch: string
  base: string
  headSha: string
  tier: Tier
  tierWhy: string
  lane: Lane
  /** The effort Codex runs at now; a timeout steps it down and reruns the round. */
  effort: Effort
  /** The effort this branch's tier and lane call for, before any carried or timeout step-down. */
  startEffort?: Effort
  /**
   * The effort the branch carries into later runs: the start, lowered only by timeouts. A re-review's capped effort (rereviewEffort)
   * is this run's alone and never carries. Absent on a run from before 1.2.0, which carries `effort`.
   */
  carriedEffort?: Effort
  /** The Codex model the gate names for this run's tier (codexModel or codexModelHigh, R69); undefined names none, so gstack's own order picks it. */
  codexModel?: string
  /** What each role reported running, from its `CODEX_MODEL:` line. A model other than the named one stops the round (R69). */
  ranModels?: RanModels
  round: number
  status: RunStatus
  phase: 'scope' | 'review' | 'fix' | 'verify' | 'collect' | 'triage' | 'done'
  /** Which side of the PR this round is on. */
  lifecycle: 'pre' | 'post'
  roundKind: RoundKind
  roundStartHead: string
  roundStartedAt: number
  /** The diff base the Codex review reads: origin/<base> before the PR, the last reviewed head after it. */
  diffBase: string
  evidence: Evidence[]
  /** Agent-step time and reviewer-wait time spent in this round so far. */
  activeMs: number
  waitMs: number
  /** Post-PR collection: when it started, when feedback last arrived, when gh was last polled. */
  collect?: { startedAt: number; lastArrivalAt: number; polledAt: number; headAt: number }
  /** Post-PR: the feedback ids handed to the main agent this round. */
  triaged?: string[]
  /** Post-PR: the finding ids the triage step was asked to answer (fresh, Codex's, carried). */
  asked?: string[]
  /** Post-PR: the security rebuttals Codex is checking (R36). */
  rechecks?: string[]
  /** Post-PR: a triage re-opened on resume for a block the agent can answer on the same head (R37); it records no round. */
  isAnswer?: true
  /** A prompt the ticker submits once the command that queued it has returned. */
  outbox?: string
  hasRefixed: boolean
  /** The fix step was asked once more about findings it left without an answer (it costs no round). */
  hasReprompted?: boolean
  /** The Codex check gave no verdict on reported fixes and ran once more (R72); a second miss leaves them owed. */
  hasRetriedCheck?: boolean
  /** What the fix step in flight (or the last one) was sent: blocking findings, or advisories alone. */
  fixKind: 'blocking' | 'advisory'
  steps: Step[]
  findings: Finding[]
  pending: Pending[]
  activity: string
  startedAt: number
  phaseStartedAt: number
  endedAt?: number
  message?: string
}

declare module 'claude-code' {
  interface PluginState {
    'pr-lifecycle': { run: Run | null; tick: number }
  }
}
